    r('non singulière est connu','non singulière est connue','second paragraph','The print has connue with a final e.')
    r('diviseurs de Cartier\npositifs','diviseurs de Cartier,\npositifs','second paragraph','A comma follows Cartier.')
    r(r'\fsection{7}{Compléments et questions}',r'\fsection{7}{\normalfont\uline{Compléments et questions}.}','section heading','The upright heading is underlined and ends in a full stop.')
