    if tree=='fr':
        r("à ce que un sous-schéma","à ce qu'un sous-schéma",'second paragraph','The obligatory elision before un is restored in corrected French.','misprint of the original')
        r('non singulière est connue','non singulière est connu','second paragraph','The subject of est connu is the masculine sous-schéma, not the embedded feminine courbe.','misprint of the original')
        r(r"\prod\limits_{S'/S}(X/S)",r"\prod\limits_{S'/S}(X/S')",'nonrepresentable Weil restriction','Restriction from S prime to S acts on the specified S-prime-scheme X; its argument must be X/S prime.','misprint of the original')
